<?php
require_once __DIR__.'/../config.php';require_admin();
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$st=$conn->prepare("DELETE FROM categories WHERE id=?");$st->bind_param("i",$id);$st->execute();$_SESSION['flash']=['type'=>'success','message'=>'Kategori dihapus.'];redirect('categories.php');}
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');if($name!==''){$st=$conn->prepare("INSERT INTO categories(name) VALUES(?)");$st->bind_param("s",$name);if($st->execute())$_SESSION['flash']=['type'=>'success','message'=>'Kategori ditambahkan.'];else$_SESSION['flash']=['type'=>'danger','message'=>'Kategori sudah ada atau gagal disimpan.'];redirect('categories.php');}}
$rows=$conn->query("SELECT c.*,COUNT(p.id) total_products FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name");include '_header.php';?>
<h1 class="h3 fw-bold mb-4">Kelola Kategori</h1><div class="card border-0 shadow-sm p-4 mb-4"><form method="post" class="d-flex gap-2"><input class="form-control" name="name" placeholder="Nama kategori baru" required><button class="btn btn-success">Tambah</button></form></div><div class="card border-0 shadow-sm"><table class="table mb-0"><thead><tr><th>Nama</th><th>Jumlah produk</th><th>Aksi</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['name'])?></td><td><?=$r['total_products']?></td><td><a class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus kategori? Produk terkait akan menjadi tanpa kategori.')" href="?delete=<?=$r['id']?>">Hapus</a></td></tr><?php endwhile;?></tbody></table></div><?php include '_footer.php';?>